<?php $labels = \App\Services\CarConfigurator::LABELS; $doneCount = count(array_filter($order['steps'])); $ratio = round(100 * $doneCount / count($labels)); ?>
<section class="page-hero shell compact"><a href="<?= current_user()['role'] === 'staff' ? '/operarios' : '/pedidos' ?>" class="back-link">← Volver a <?= current_user()['role'] === 'staff' ? 'operarios' : 'mis pedidos' ?></a><span class="kicker">SEGUIMIENTO</span><h1>Pedido <em>#<?= (int) $order['id'] ?>.</em></h1><div class="detail-meta"><span class="status status-<?= e($order['status']) ?>"><?= e(\App\Models\Order::STATUS[$order['status']] ?? $order['status']) ?></span><span>Encargo de <?= e($order['customer_name']) ?></span><span><?= date_es($order['created_at']) ?></span></div></section>
<section class="section shell detail-layout"><div><div class="surface"><div class="section-heading"><h2>Estado de fabricación</h2><strong class="large-percentage"><?= $ratio ?>%</strong></div><div class="progress-track progress-large"><div class="progress-fill" style="width:<?= $ratio ?>%"></div></div><div class="timeline"><?php foreach ($labels as $category => $label): ?><?php $completed = !empty($order['steps'][$category]); ?><div class="timeline-item <?= $completed ? 'is-done' : '' ?>"><span class="timeline-symbol"><?= $completed ? '✓' : '○' ?></span><div><strong><?= e($label) ?></strong><small><?= $completed ? 'Completado el ' . date_es($order['steps'][$category]) : 'Pendiente de fabricación' ?></small></div></div><?php endforeach; ?></div></div>
<?php if (current_user()['role'] === 'staff'): ?><div class="surface space-top"><h2>Actualizar fabricación</h2><p class="muted">Marca las fases completadas y guarda los cambios.</p><form action="/operarios/pedidos/<?= (int) $order['id'] ?>" method="post" class="stack-form"><?= csrf_field() ?><div class="check-list"><?php foreach ($labels as $category => $label): ?><label><input type="checkbox" name="done[]" value="<?= e($category) ?>" <?= !empty($order['steps'][$category]) ? 'checked' : '' ?>><span><?= e($label) ?></span></label><?php endforeach; ?></div><button class="btn btn-primary" type="submit">Guardar avance ↗</button></form></div><?php endif; ?></div><aside><div class="surface"><span class="card-overline">DESGLOSE DE TU COCHE</span><h2>Componentes</h2><div class="breakdown"><?php foreach ($order['items'] as $item): ?><div><span><small><?= e($labels[$item['category']] ?? $item['category']) ?></small><strong><?= e($item['part_name']) ?></strong></span><b><?= money($item['unit_price']) ?></b></div><?php endforeach; ?></div><div class="breakdown-total"><span>Total estimado</span><strong><?= money($order['total']) ?></strong></div></div></aside></section>